function check(value) { console.log(Number.isNaN(value), Number.isFinite(value)); }
console.log(Number.isNaN(), Number.isFinite());
check(NaN);
check(0 / 0);
check(Infinity);
check(-Infinity);
check(0);
check(-0);
check(42);
check(-1.5);
check('NaN');
check('0');
check('');
check(true);
check(false);
check(null);
check(undefined);
check({});
check(function() { return 1; });
let effects = '';
let object = { valueOf: function() { effects = effects + 'v'; throw 'coerced'; }, toString: function() { effects = effects + 's'; throw 'coerced'; } };
check(object);
console.log(effects === '');
let detachedNaN = Number.isNaN;
let detachedFinite = Number.isFinite;
let receiver = { nan: detachedNaN, finite: detachedFinite };
console.log(detachedNaN(NaN), detachedFinite(3), receiver.nan(NaN), receiver.finite(3));
function extra(tag) { effects = effects + tag; return NaN; }
console.log(Number.isNaN(extra('a'), extra('b'), extra('c')), effects);
console.log(Number.isFinite(3, extra('d'), extra('e')), effects);
console.log(Number.isNaN(0, NaN), Number.isFinite(Infinity, 0));
console.log(Number.isNaN(Number.NaN), Number.POSITIVE_INFINITY === Infinity, Number.NEGATIVE_INFINITY === -Infinity);
console.log(Number.MAX_VALUE, Number.MIN_VALUE, Number.EPSILON);
console.log(Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER);
console.log(Number.MAX_VALUE * 2 === Infinity, Number.MIN_VALUE / 2 === 0, 1 + Number.EPSILON > 1);
console.log(Number.isFinite(Number.MAX_VALUE), Number.isFinite(Number.MIN_VALUE), 1 / -0 === -Infinity);
console.log(Number.isNaN.name, Number.isNaN.length, Number.isFinite.name, Number.isFinite.length);
Number.isNaN = function(value) { return value; };
console.log(Number.isNaN(23));
Number = 17;
console.log(Number);
